INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES
('devops', 'capacity-planning', 'overview', 'How does capacity planning differ from defining SLOs?', '["They are the same discipline under two different names", "SLOs define the reliability target; capacity planning is the separate discipline of ensuring enough infrastructure exists to actually hit that target under real and projected load", "Capacity planning replaces the need for SLOs entirely", "SLOs are set by capacity planners, not by product or SRE teams"]', 1, 'The content frames these as two different questions: SLOs answer ''what reliability do we promise?'' while capacity planning answers ''do we have enough headroom to deliver it?'' -- an SRE needs both.', 'beginner'),
('devops', 'capacity-planning', 'overview', 'In the core capacity planning loop, what does step 3 (determine headroom needed) typically call for?', '["Sizing for exactly the measured average load, with zero margin", "Sizing for peak load plus a safety margin, commonly 20-40%, higher for unpredictable traffic", "Sizing for double the current peak load regardless of predictability", "Sizing based solely on the previous year''s Black Friday numbers"]', 1, 'The core loop''s headroom step specifically calls for peak load plus a safety margin (commonly 20-40%), with the higher end reserved for services with unpredictable traffic.', 'intermediate'),
('devops', 'capacity-planning', 'overview', 'What is the difference between load testing and stress testing?', '["They are identical; the terms are used interchangeably", "Load testing simulates expected peak traffic to confirm the system holds up; stress testing pushes well beyond expected peak specifically to find the actual breaking point", "Load testing only applies to databases; stress testing only applies to APIs", "Stress testing is a subset of load testing with lower traffic volume"]', 1, 'Load testing validates the system holds at expected peak; stress testing deliberately goes beyond expected peak to find where things actually break -- two different questions with two different answers.', 'beginner'),
('devops', 'capacity-planning', 'overview', 'What does ''cost-aware headroom'' mean at a senior capacity-planning level?', '["Always provisioning the maximum headroom possible to eliminate all risk", "Finding the minimum headroom that reliably meets demand, not the maximum headroom that feels safe -- since over-provisioning is a real, ongoing cost", "Refusing to provision any headroom at all to minimize cost", "Outsourcing all capacity decisions to the cloud provider''s default autoscaling settings"]', 1, 'The overview is explicit: senior-level capacity planning is about finding the minimum headroom that reliably works, since over-provisioning ''just to be safe'' is a real, recurring cost, not a one-time safety purchase.', 'intermediate'),
('devops', 'capacity-planning', 'overview', 'Per the overview''s relationship-to-SLOs framing, what is capacity planning''s role relative to an SLO''s error budget?', '["Capacity planning has no relationship to error budgets at all", "An SLO tells you when you''re in trouble (error budget burning down); capacity planning is what happens before that, provisioning ahead of demand so the error budget never has to be spent on a preventable capacity shortfall", "Capacity planning is only relevant after an error budget is fully exhausted", "Error budgets are calculated directly from capacity planning headroom percentages"]', 1, 'The relationship is proactive: capacity planning aims to provision ahead of demand specifically so a preventable capacity shortfall never has to burn the error budget an SLO permits.', 'intermediate'),
('devops', 'capacity-planning', 'fundamentals', 'Why is measuring average CPU utilization instead of peak utilization a common baseline mistake?', '["Average utilization is always higher than peak, so it overestimates need", "A service averaging 40% CPU can still regularly spike to 85% during a specific hourly window, and average-based planning would miss that entirely", "CPU is not a meaningful metric for capacity planning at all", "Peak utilization cannot be measured with standard monitoring tools"]', 1, 'The fundamentals content gives this exact example: a 40% daily average can hide a genuine 85% spike during a specific peak window -- averaging smooths over exactly the signal that matters for headroom sizing.', 'intermediate'),
('devops', 'capacity-planning', 'fundamentals', 'What is the actual number to design against when running a load test, per the fundamentals content?', '["Whether the test technically completes without crashing the load-testing tool itself", "The specific point where a measured metric (P99 latency, error rate) crosses an unacceptable threshold as load increases -- not simply ''does it work''", "The total dollar cost of running the load test", "The number of virtual users the load-testing tool''s free tier allows"]', 1, 'The content is explicit: run at increasing VU counts until a real metric (P99 latency, error rate) crosses an unacceptable threshold -- that measured ceiling, not a pass/fail guess, is what headroom should be planned against.', 'intermediate'),
('devops', 'capacity-planning', 'fundamentals', 'Why is soak testing specifically necessary, distinct from load and stress testing?', '["Soak testing is just a slower version of stress testing with no additional value", "Soak testing runs sustained moderate load over hours, which is specifically what catches memory leaks and slow degradation that a short 10-minute load test would never reveal", "Soak testing is only relevant for database services, never for stateless application services", "Soak testing replaces the need for both load and stress testing entirely"]', 1, 'The content flags soak testing as catching a distinct failure class -- slow leaks and degradation -- that a short test simply doesn''t run long enough to expose, and notes skipping it is a common real gap.', 'intermediate'),
('devops', 'capacity-planning', 'fundamentals', 'Why can''t the listed scaling thresholds (e.g. CPU > 70% sustained for 5 min) be treated as a universal constant across all services?', '["Because Kubernetes technically enforces a single global threshold for all services regardless of configuration", "A service with genuinely spiky, unpredictable traffic needs a lower CPU trigger and faster scale-out reaction time than a service with smooth, predictable load, given how fast demand can grow within the autoscaler''s actual reaction time", "Because scaling thresholds only apply to memory, never to CPU", "Because thresholds must be identical across every environment (dev, staging, production) by platform requirement"]', 1, 'The margin between triggering a scale event and actually running out of capacity needs to account for how fast demand can realistically grow for that specific service -- a spiky service needs a more conservative (lower) trigger than a smooth one.', 'intermediate'),
('devops', 'capacity-planning', 'fundamentals', 'What does the 20-40% headroom margin actually buy you, according to the fundamentals content?', '["It is purely padding with no specific functional purpose", "It specifically buys reaction time -- if a scale-out takes 3 minutes to bring new capacity online, headroom is what absorbs the load during those 3 minutes without breaching SLO", "It is required by cloud provider terms of service for all production workloads", "It guarantees zero cost increase compared to provisioning at exact peak"]', 1, 'The margin isn''t arbitrary padding -- it specifically covers the gap between a scale event triggering and new capacity actually coming online, absorbing load during that reaction window without breaching SLO.', 'intermediate'),
('devops', 'capacity-planning', 'intermediate', 'What does seasonal decomposition specifically prevent when forecasting demand?', '["It prevents any forecasting from being done at all until a full year of data exists", "It stops a real seasonal spike (predictable, recurring) from being mistaken for permanent trend growth, and equally stops a genuine trend shift from being dismissed as seasonal noise", "It eliminates the need to ever run a load test", "It only applies to e-commerce platforms, not to other service types"]', 1, 'Decomposition separates genuine underlying trend from recurring seasonal patterns (like a Diwali spike) -- without it, a one-time seasonal event risks being folded into a permanent-growth forecast, over-provisioning based on a spike that won''t recur at that scale outside the season.', 'advanced'),
('devops', 'capacity-planning', 'intermediate', 'Why is the deliberate asymmetry in the HPA example (scaleUp stabilizationWindowSeconds: 0 vs scaleDown stabilizationWindowSeconds: 300) the right design, not something to blindly copy?', '["Because scaling up should always be slower than scaling down for cost reasons", "Scaling up fast avoids an SLO breach during a real spike, while scaling down slowly avoids thrashing -- scaling in too eagerly on a slight dip, then having to scale back out minutes later, wasting the reaction-time margin headroom exists to provide", "Because Kubernetes technically requires scaleDown to always be at least 300 seconds", "Because this specific configuration works identically well for every workload regardless of traffic pattern"]', 1, 'The asymmetry is deliberate: fast scale-up protects against missing a real spike, while slow scale-down specifically prevents thrashing (eager scale-in immediately followed by scaling back out) that wastes the very reaction-time margin headroom is meant to buy.', 'advanced'),
('devops', 'capacity-planning', 'intermediate', 'Why is CPU/memory utilization a genuinely misleading scaling signal for queue-processing services?', '["CPU and memory metrics are never available for queue-based workers", "A worker can be at low CPU while a queue backs up simply because there aren''t enough workers running, or work items are slow for reasons unrelated to CPU (waiting on an external API) -- queue depth relative to consumption rate directly targets the actual problem instead", "Queue-processing services never experience any capacity issues by design", "CPU-based scaling is always faster to react than queue-depth-based scaling"]', 1, 'A queue backing up isn''t necessarily a CPU problem -- workers can be idle-looking (low CPU) while a queue grows because there simply aren''t enough of them, or because work is slow for reasons CPU metrics don''t capture at all.', 'intermediate'),
('devops', 'capacity-planning', 'intermediate', 'What is the correct order of operations for planning a known high-traffic event, per the intermediate content?', '["Rely entirely on reactive autoscaling with no pre-planning, since the event timing is already known", "Forecast expected peak using the best available signal, run a dedicated load test at that forecast plus margin well before the event, pre-scale ahead of the event rather than relying solely on reactive autoscaling, and have an explicit rollback/circuit-breaker plan for exceeding even that forecast", "Wait until the event starts, then scale reactively based on real-time metrics alone", "Skip load testing entirely since the event traffic pattern is already known from marketing estimates"]', 1, 'The described sequence is: forecast peak, run a dedicated load test at forecast+margin well in advance, pre-scale ahead of the event (since a launch-day ramp can outpace normal autoscaler reaction time), and have an explicit fallback plan if reality exceeds even that forecast.', 'intermediate'),
('devops', 'capacity-planning', 'intermediate', 'What is specifically named as often more valuable than additional pre-provisioning when actual event traffic exceeds even the forecast-plus-margin?', '["Immediately declaring a company-wide P1 incident regardless of actual user impact", "A feature flag to degrade gracefully -- disabling a non-critical, expensive feature -- in the moment", "Purchasing additional cloud capacity at whatever the current spot price happens to be", "Rolling back the entire application to the previous major version"]', 1, 'The content specifically names a graceful-degradation feature flag (disabling a non-critical expensive feature) as often more valuable in the moment than more pre-provisioning, as the explicit rollback/circuit-breaker plan for exceeding forecast.', 'advanced'),
('devops', 'capacity-planning', 'advanced', 'Why is capacity planning for stateful services (like databases) fundamentally harder than for stateless services?', '["Stateful services never need capacity planning because they don''t experience load", "Write capacity in most relational databases doesn''t scale by adding nodes the same way read capacity does via replicas -- it scales via vertical scaling (with a real ceiling) or sharding (a significant engineering project), so read and write load need to be forecast and planned separately", "Stateful services always require exactly 3x the headroom of stateless services by a fixed rule", "Stateful services can only run on a single cloud provider, complicating capacity math"]', 1, 'Read capacity scales via replicas (a capacity-planning knob); write capacity scales via vertical scaling or sharding (a much bigger, slower engineering project) -- conflating the two into one number misses that they have entirely different scaling paths and lead times.', 'advanced'),
('devops', 'capacity-planning', 'advanced', 'What three inputs make up the ''rough framework'' for right-sizing headroom, instead of just picking a flat 30% margin?', '["The team''s total headcount, the company''s annual revenue, and the current cloud spend budget", "The autoscaler''s actual measured reaction time under real load, the fastest realistic traffic ramp rate for that specific service, and a margin for forecast error specifically", "The number of Kubernetes nodes currently provisioned, the cluster''s Kubernetes version, and the ingress controller in use", "The time of day, the day of the week, and the current weather conditions in the primary data center region"]', 1, 'The framework specifically weighs measured (not theoretical) autoscaler reaction time, the realistic traffic ramp rate for that particular service, and a distinct margin for forecast error -- not a flat percentage copied from an unrelated service.', 'advanced'),
('devops', 'capacity-planning', 'advanced', 'Why does a multi-region architecture designed for failover need each region''s steady-state capacity to already include headroom for the failover scenario?', '["Because cloud providers require every region to be provisioned identically by policy", "If region B needs to absorb region A''s full traffic during a regional failover, provisioning each region only for its own normal steady-state traffic means a real regional failure doubles load onto a region sized for half of that", "Because failover headroom is automatically provisioned by the cloud provider at no additional cost", "Because Kubernetes automatically redistributes capacity between regions during a failover event"]', 1, 'If each region is only sized for its own normal traffic, a real failover doubles the load onto the surviving region without the capacity to absorb it -- the failover headroom has to be carried as real, ongoing (mostly idle) capacity, a genuine cost tradeoff worth being explicit about.', 'advanced'),
('devops', 'capacity-planning', 'advanced', 'How does using chaos engineering to validate capacity assumptions differ from using it to validate failure handling?', '["There is no meaningful difference -- both test exactly the same thing", "Deliberately removing a fraction of capacity (killing replicas, forcing a regional failover) tests whether the *remaining* capacity actually absorbs the load as forecast, not just whether the system fails gracefully in the abstract -- turning a capacity hypothesis (''we have 40% headroom'') into a genuinely tested measurement", "Chaos engineering can only validate failure handling, never capacity assumptions", "Capacity validation via chaos engineering requires a completely different, incompatible toolset from failure-handling chaos experiments"]', 1, 'The distinction is what''s being measured: failure-handling chaos confirms the system degrades gracefully; capacity-validation chaos specifically measures whether the remaining capacity after a controlled reduction actually absorbs real load as forecast -- turning an assumed headroom number into a tested one.', 'advanced'),
('devops', 'capacity-planning', 'advanced', 'What is described as the single biggest structural mistake in mature capacity planning?', '["Setting the safety margin too high instead of too low", "Treating capacity planning as a periodic (quarterly, pre-launch) exercise rather than a continuous one, since traffic patterns, dependencies, and cost structures all drift continuously between scheduled reviews", "Using load testing tools instead of stress testing tools", "Delegating all capacity decisions to a single senior engineer instead of a team"]', 1, 'The content is explicit: the biggest mistake isn''t a wrong forecast, it''s treating capacity planning as periodic rather than continuous -- a model built once goes stale before the next scheduled review catches it, which is why key signals should be part of ongoing automated reporting.', 'advanced'),
('devops', 'automation', 'overview', 'What is ''toil'' in the SRE automation sense, and what happens if it exceeds 50% of a team''s time?', '["Toil is any work at all, including design docs and architecture reviews; exceeding 50% means the team gets a bonus", "Toil is repetitive, manual, automatable work that scales linearly with service growth; if it exceeds 50% of working hours, the team drowns -- there''s no bandwidth left for the engineering work that would reduce it", "Toil only refers to on-call pager duty specifically; exceeding 50% triggers automatic escalation to a VP", "Toil is a measure of infrastructure cost, unrelated to engineering time"]', 1, 'Toil is specifically repetitive, manual, automatable work scaling with service growth -- once it exceeds 50% of a team''s time, there''s structurally no time left for the automation/architecture work that would reduce toil going forward.', 'beginner'),
('devops', 'automation', 'overview', 'What does GitOps deployment automation eliminate, per the overview?', '["The need for any testing before deployment", "Zero manual kubectl apply in production -- developer pushes code, CI builds the image, updates Helm values, and ArgoCD detects and deploys automatically", "The need for a Git repository to store application code", "The need for any monitoring after deployment"]', 1, 'GitOps automation is described specifically as eliminating manual kubectl apply against production -- the pipeline updates Helm values, and ArgoCD detects and deploys, with zero manual deployment commands.', 'beginner'),
('devops', 'automation', 'overview', 'What does KEDA (Kubernetes Event-Driven Autoscaling) scale based on, that distinguishes it from typical CPU/memory-based HPA?', '["It only scales based on the time of day", "External signals like queue depth or message count, not just CPU/memory", "It scales based on the number of currently logged-in users only", "It does not perform scaling at all -- it only sends alerts"]', 1, 'KEDA is specifically called out for scaling based on external signals like queue depth or message count -- distinct from the CPU/memory metrics a standard HPA typically relies on.', 'beginner'),
('devops', 'automation', 'overview', 'What is the stated benefit of alert correlation, per the overview?', '["It eliminates the need for any alerting system entirely", "Grouping 50 symptom alerts into 1 root-cause incident, reducing alert fatigue and improving MTTR", "It automatically fixes the root cause without any human or automated remediation", "It replaces the need for a post-mortem process"]', 1, 'Alert correlation groups many related symptom alerts into a single root-cause incident, directly reducing alert fatigue and improving MTTR by avoiding redundant, separate triage of each symptom.', 'intermediate'),
('devops', 'automation', 'overview', 'What is the target MTTR for auto-remediated incidents, per the automation success metrics table?', '["Under 5 minutes", "Under 24 hours", "Exactly 1 hour", "There is no defined target -- it varies case by case"]', 0, 'The measuring-success table lists a target of under 5 minutes MTTR specifically for auto-remediated incidents -- confirming remediation is genuinely faster than a human response.', 'beginner'),
('devops', 'automation', 'fundamentals', 'What are the defining characteristics of toil per the precise definition given in the fundamentals content?', '["Anything that takes more than 10 minutes to complete", "Manual, repetitive, automatable, tactical (no lasting value once done), and scales linearly with service growth", "Any task assigned to a junior engineer rather than a senior one", "Work that involves writing code, as opposed to writing documentation"]', 1, 'The fundamentals content gives a precise five-part definition -- manual, repetitive, automatable, tactical with no lasting value, and scaling linearly with growth -- explicitly distinguishing toil from other manual-but-non-toil work like writing a design doc.', 'intermediate'),
('devops', 'automation', 'fundamentals', 'Why is a silently-failing automation script described as worse than no automation at all?', '["Because failed scripts always cost more in cloud compute than successful ones", "A human notices when they can''t complete a task and escalates; a failed script that doesn''t escalate leaves the original problem unaddressed with nobody aware it''s still happening", "Because silent failures are always caused by a bug in the automation platform itself, not the script", "Silent failures are not actually worse -- the framing is a common misconception the content corrects"]', 1, 'The comparison is specifically about awareness: a human who fails at a task notices and raises it, while a script that fails silently leaves the underlying problem both unaddressed and undetected -- worse than the manual process it replaced.', 'intermediate'),
('devops', 'automation', 'fundamentals', 'What three properties make a failure a strong candidate for auto-remediation, per the fundamentals content''s generalization of the OOMKilled example?', '["The failure must be rare, expensive to diagnose, and involve customer-facing data", "Well-understood, safe to retry without side effects, and has a clear, deterministic fix", "The failure must have occurred at least 10 times in the past month", "The failure must only affect non-production environments"]', 1, 'The content generalizes from the OOMKilled restart example: a strong auto-remediation candidate is well-understood, safe to retry without side effects, and has a clear deterministic fix -- an ambiguous or retry-risky failure (like double-processing a payment) is explicitly not a good candidate.', 'advanced'),
('devops', 'automation', 'fundamentals', 'How does the fundamentals content connect the Capacity Planning academy content to the HPA automation example shown?', '["It states the two topics are entirely unrelated and should not be studied together", "The thresholds and headroom reasoning from Capacity Planning is what determines what the HPA config should actually say -- automation here executes a capacity decision already made, not a substitute for making it correctly", "It claims HPA automation makes capacity planning entirely unnecessary", "It states capacity planning should only be done after automation is already fully built"]', 1, 'The content is explicit that automation (the HPA config) is the execution mechanism for a capacity decision that Capacity Planning content elsewhere determines the actual numbers for -- automation doesn''t replace that decision-making.', 'intermediate'),
('devops', 'automation', 'fundamentals', 'Why can automation effort itself quietly become a form of toil, per the fundamentals content''s closing point?', '["Because writing automation code is itself always classified as toil by definition", "Building automation for its own sake, without measuring whether it''s actually reducing manual work or improving MTTR, is a real trap -- automation effort not confirmed against outcomes isn''t delivering its intended value", "Because automation scripts require constant manual restarting to keep running", "Because automation always increases toil in the short term with no possible long-term benefit"]', 1, 'The point is about measurement, not automation itself: automation that isn''t tracked against real outcomes (toil percentage, MTTR, manual intervention rate) can be built without actually confirming it reduces manual work -- a trap worth guarding against explicitly.', 'advanced'),
('devops', 'automation', 'intermediate', 'What is the real MTTR improvement mechanism from alert correlation, per the intermediate content?', '["Correlation makes individual alerts fire faster than they otherwise would", "An on-call engineer immediately sees ''one database outage, 50 downstream symptoms'' instead of separately triaging 50 alerts before independently arriving at the same conclusion -- eliminating a repeated manual pattern-recognition task", "Correlation automatically resolves the root cause without any further action needed", "Correlation reduces the total number of alerts generated by the monitoring system itself"]', 1, 'The improvement isn''t from responding to each alert faster -- it''s from skipping the repeated manual pattern-recognition of realizing 50 separate-looking alerts share one root cause, which correlation surfaces immediately instead.', 'intermediate'),
('devops', 'automation', 'intermediate', 'Why does a shallow liveness check (just confirming the process responds to a ping) miss an entire category of real failures?', '["Shallow checks are always slower to execute than deep checks, causing timeouts", "A service can be technically ''up'' and responding to a ping while functionally broken -- e.g. its DB connection pool is exhausted and every real request fails, while the process itself never crashes -- so a shallow check never triggers a restart", "Shallow checks only work for stateless services, never for any Kubernetes-managed workload", "Kubernetes does not support shallow liveness checks at all, making the scenario impossible"]', 1, 'A process can be alive (responds to a ping) but functionally broken (exhausted DB pool, every real request failing) -- a shallow check never fails in that case, so self-healing never triggers even though the service is genuinely down for real traffic.', 'intermediate'),
('devops', 'automation', 'intermediate', 'In the GitOps automation pipeline described, what deliberate human checkpoint remains even in a fully automated setup?', '["A human must manually run kubectl apply for every single deployment", "PR review before merge -- full GitOps automation removes manual execution risk, not the human judgment decision of whether a change should deploy", "A human must manually verify every container image''s SHA-256 hash before each deploy", "A human must physically restart the CI runner before each pipeline execution"]', 1, 'The content specifically calls out PR review as the retained human checkpoint -- GitOps removes manual execution risk (mistyped commands, undocumented changes) while keeping the ''should this deploy'' decision explicit and reviewed.', 'intermediate'),
('devops', 'automation', 'intermediate', 'What does the AUTOMATED_REMEDIATION_MAP pattern (an explicit, reviewed allowlist of alert-to-action mappings) protect against?', '["It protects against the automation platform running out of memory", "Automating ''run some remediation for whatever alert comes in'' without an explicit mapping, which is how automation ends up taking an inappropriate action for an alert nobody intended it to handle", "It protects against PagerDuty sending duplicate webhook notifications", "It protects against a developer accidentally deleting the automation script''s source code"]', 1, 'The explicit, reviewed mapping ensures every alert-to-automated-action pairing is a deliberate decision, reviewed like a production code change -- an implicit catch-all risks the automation acting on an alert nobody intended it to handle.', 'advanced'),
('devops', 'automation', 'intermediate', 'When should automation escalate to a human instead of acting, even when a script could technically perform the action?', '["Automation should always act first and escalate only if the action visibly fails", "When there''s unclear scope, an unfamiliar error signature, or any risk of data loss on retry -- the failure should route to a human with pre-gathered diagnostic context rather than an automated action in a genuinely ambiguous situation", "Automation should never escalate to a human under any circumstances, since that defeats its purpose", "Only when the failure occurs outside of normal business hours"]', 1, 'The judgment call is distinguishing safe-to-auto-remediate from needs-a-human-but-enrich-first -- ambiguous scope, unfamiliar errors, or retry-with-data-loss-risk situations should route to a human with automation-gathered context, not an automated action.', 'intermediate'),
('devops', 'automation', 'advanced', 'What is the central risk that comes packaged with automated remediation''s core value proposition of speed?', '["Automated remediation is always slower than manual remediation, contradicting its own value proposition", "An automated action that''s wrong executes just as fast as one that''s right, potentially causing real damage before any human has a chance to notice something''s off", "Automated remediation always costs more in cloud compute than the incident it''s meant to prevent", "Automated remediation can only ever be applied to non-production environments"]', 1, 'Speed is automation''s entire value proposition and its central risk simultaneously -- a wrong automated action executes with the same speed as a correct one, with no human verification window before potential damage occurs.', 'advanced'),
('devops', 'automation', 'advanced', 'What does the RemediationCircuitBreaker pattern specifically protect against?', '["It protects against the remediation script consuming too much CPU on a single run", "A remediation loop that keeps re-triggering (restart, still failing, restart again) without ever escalating to a human -- stopping auto-acting after repeated failures within a time window and escalating instead of retrying indefinitely", "It protects against two different engineers running conflicting remediation scripts simultaneously", "It protects against the monitoring system itself going down during an incident"]', 1, 'The circuit breaker caps repeated automated attempts within a time window and forces escalation once exhausted -- guarding specifically against a broken deployment triggering dozens of masking restarts that never actually fix the underlying problem.', 'advanced'),
('devops', 'automation', 'advanced', 'What is described as the ''most dangerous automation mistake,'' distinct from a script that fails loudly?', '["An automation script that takes longer than 5 minutes to run", "Automation that successfully suppresses the symptom of a real, worsening problem without anyone noticing -- e.g. an auto-restart that ''fixes'' a memory leak every time it approaches OOM, making the leak invisible until it eventually outpaces even frequent restarts", "An automation script that requires manual approval before running", "An automation script written in a scripting language instead of a compiled one"]', 1, 'The most dangerous failure isn''t a loud crash -- it''s silent symptom suppression, where an auto-restart masks a worsening leak from normal monitoring until the underlying problem eventually outpaces even frequent remediation, causing a worse outage with less warning.', 'advanced'),
('devops', 'automation', 'advanced', 'How does chaos engineering validate SRE automation, and what specific gap does this close?', '["It cannot validate automation at all -- chaos engineering only applies to infrastructure resilience, not remediation scripts", "Deliberately triggering the exact failure the automation is meant to handle, in a controlled environment, confirms the automation still works -- closing the gap where correct-when-written automation silently stops working after an unrelated change (a deprecated API, a renamed label selector)", "It validates automation exclusively by reviewing the automation''s source code for syntax errors", "It replaces the need for the RemediationCircuitBreaker pattern entirely"]', 1, 'Automated remediation is itself a hypothesis (''when X fails, this script fixes it'') until tested -- chaos engineering deliberately triggers the exact condition to confirm the automation still works, catching silent breakage (an API deprecation, a selector mismatch) before a real incident is the first test.', 'advanced'),
('devops', 'automation', 'advanced', 'Per the automation maturity model, where do most teams building SRE automation stop, and what does the next jump mostly require?', '["Most teams reach ''Validated'' immediately; the jump to further levels requires new tooling only", "Most teams stop at ''Triggered''; the jump to ''Guarded'' is mostly a design discipline (circuit breakers, escalation paths, visibility) rather than new tooling", "Most teams never get past ''Reactive''; the jump to ''Triggered'' requires hiring a dedicated automation team", "Maturity levels are purely theoretical and no real team maps onto any of them"]', 1, 'The model places most teams at ''Triggered'' (automation runs from alerts but lacks circuit breakers/escalation); reaching ''Guarded'' is framed as mainly a design-discipline change, not a new-tooling problem, and worth prioritizing before expanding automation''s scope.', 'advanced'),
('devops', 'cicd', 'overview', 'What is the precise difference between Continuous Delivery and Continuous Deployment?', '["They are the same practice with two different names used interchangeably", "Continuous Delivery automatically deploys to staging after CI passes, ready to release at any time; Continuous Deployment goes further, with code going to production after all checks pass, fully automated", "Continuous Delivery only applies to mobile apps; Continuous Deployment only applies to web services", "Continuous Deployment requires manual approval at every stage, while Continuous Delivery requires none"]', 1, 'The overview distinguishes CI (build+test on every commit) from Delivery (auto-deploy to staging, release-ready) from Deployment (fully automated all the way to production after all checks pass).', 'beginner'),
('devops', 'cicd', 'overview', 'In the airport security checkpoint analogy for a CI/CD pipeline, what does a failed bag scan represent?', '["A successful deployment to production", "A failed test/check stage that stops the pipeline cold, so a broken build never reaches production just because nobody caught it manually", "The moment code is first committed to the repository", "A scheduled maintenance window for the CI/CD platform itself"]', 1, 'The analogy maps a failed bag scan to a failed pipeline stage: it stops you (the code) right there, the same way a pipeline stops cold on a failed test rather than quietly letting a broken build continue toward production.', 'beginner'),
('devops', 'cicd', 'overview', 'Per the deployment strategies table, which strategy offers instant rollback speed?', '["Rolling update", "Blue/Green -- an atomic traffic switch back to the still-running previous environment", "Canary", "Recreate"]', 1, 'Blue/Green''s rollback is instant because it''s just an atomic traffic switch back to the still-running ''blue'' environment -- no rebuild or redeploy needed, unlike rolling update or recreate.', 'intermediate'),
('devops', 'cicd', 'overview', 'How does the overview describe GitOps as implemented by tools like ArgoCD?', '["A manual process where an engineer runs kubectl apply after each code review", "A pattern where Git itself is the single source of truth for what should be running; a controller inside the cluster continuously watches the Git repo and pulls changes into the cluster, rather than the pipeline pushing them in", "A backup strategy for storing Kubernetes manifests in case of data loss", "A code review tool unrelated to actual deployment mechanics"]', 1, 'GitOps specifically means Git is the source of truth and a cluster-side controller pulls changes from it continuously -- the inverse of a pipeline pushing changes directly into the cluster.', 'intermediate'),
('devops', 'cicd', 'overview', 'In the ''Try It'' GitHub Actions demo, why does the ''Deploying to production...'' step get skipped entirely (shown grayed out) rather than shown as failed, once the test step fails?', '["Because GitHub Actions runs all steps in parallel regardless of earlier failures", "Because a pipeline''s fail-fast behavior means a later stage simply never executes once an earlier stage fails -- it''s skipped, not run-and-failed, with zero manual intervention needed to stop it", "Because the deploy step was manually disabled in the workflow file before the demo started", "Because GitHub Actions has a daily quota limit that was reached mid-run"]', 1, 'This demonstrates fail-fast pipeline behavior concretely: once an earlier stage fails, later stages are skipped entirely (not attempted and failed) -- exactly the mechanism that stops a broken build from ever reaching a real deploy step.', 'intermediate'),
('devops', 'cicd', 'fundamentals', 'What is the precise distinction between Continuous Delivery and Continuous Deployment that the fundamentals content says ''trips people up constantly in interviews''?', '["Delivery is for mobile apps, Deployment is for web apps -- a platform distinction", "Delivery = always release-ready, a human decides when to release; Deployment = no human gate at all, every passing change deploys to production automatically", "Delivery requires a paid CI/CD platform; Deployment can be done with free tools only", "Deployment happens before testing; Delivery happens after testing"]', 1, 'The content states this exact distinction as the interview trap: Delivery keeps every change release-ready with a human deciding when, while Deployment removes that human gate entirely -- and notes most real organizations practice Delivery, not full Deployment.', 'beginner'),
('devops', 'cicd', 'fundamentals', 'Why does it matter that modern CI/CD pipelines are defined as code (a YAML file in the same repo), rather than configured in a separate UI?', '["It has no real practical benefit -- it''s purely a stylistic preference among CI/CD platforms", "The pipeline definition is version-controlled alongside the code, changes go through the same PR review process as code changes, and a given commit''s pipeline behavior is reproducible even when checking out an old commit later", "It makes the pipeline run measurably faster than a UI-configured one", "It is required by law in most jurisdictions for regulated industries"]', 1, 'Defining pipelines as code specifically enables version control, PR-based review of pipeline changes, and reproducibility tied to a specific commit -- a meaningful shift from older CI tools with UI-only, disconnected configuration.', 'intermediate'),
('devops', 'cicd', 'fundamentals', 'What is wrong with automating only the deploy step, with no automated testing gate before it, per the fundamentals content''s ''common beginner misconception''?', '["Nothing is wrong with it -- deploy automation alone is the entire point of CI/CD", "It''s automating the fast delivery of broken code to production -- the actual value of CI/CD comes from the testing/verification gates between stages, not from speed alone; a pipeline with no tests is just a fancy deploy script", "It technically cannot be configured in any major CI/CD platform", "It is only a problem for pipelines deploying to Kubernetes specifically"]', 1, 'The content directly corrects this misconception: CI/CD''s value comes from the verification gates between stages, not deployment speed alone -- automating deploy without automated testing just ships broken code faster.', 'beginner'),
('devops', 'cicd', 'fundamentals', 'Why does the CI/CD platform spin up a fresh, ephemeral execution environment for each pipeline run, rather than reusing a persistent one?', '["To reduce the CI/CD platform''s own hosting costs, as the primary reason", "It guarantees ''works on my machine'' issues get caught, since the pipeline never inherits a local machine''s (or a stale runner''s) leftover state", "Because ephemeral environments are technically required by the Git protocol", "To make pipeline logs easier to read by starting with a blank terminal"]', 1, 'A fresh, ephemeral environment per run ensures the build/test never silently depends on some prior run''s leftover state -- specifically catching the class of bug where something ''works on my machine'' but wouldn''t work from a truly clean environment.', 'intermediate'),
('devops', 'cicd', 'fundamentals', 'What does `set -e` do in the fundamentals'' local bash ''Try It'' example, and what does it demonstrate?', '["It sets an environment variable named ''e'' for later use in the script", "It makes the script exit immediately when any command returns a non-zero exit code -- demonstrating the exact fail-fast mechanism behind every CI/CD pipeline''s stage ordering, just run locally", "It enables verbose debug logging for every command in the script", "It schedules the script to run automatically every time a file changes"]', 1, 'set -e causes the script to halt the instant a command fails (like the simulated false test failure), which is exactly the mechanical idea behind pipeline stage-ordering -- demonstrated locally without needing an actual CI platform.', 'intermediate'),
('devops', 'cicd', 'intermediate', 'What is described as the single biggest speed lever most teams underuse in pipeline design?', '["Switching to a more expensive CI/CD platform tier", "Caching dependency directories (node_modules, .m2, pip cache, Docker layers) keyed by a lockfile hash, so an unchanged lockfile reuses the cache instead of reinstalling from scratch on every run", "Running every pipeline stage on the largest available runner instance size", "Reducing the number of automated tests to make the suite run faster"]', 1, 'Dependency caching keyed by a lockfile hash is called out specifically -- an unchanged lockfile means the install step drops from minutes to seconds, with the wasted-time impact compounding significantly across many daily pipeline runs.', 'intermediate'),
('devops', 'cicd', 'intermediate', 'What critical detail do people commonly get wrong about environment promotion (dev to staging to production)?', '["They deploy to staging before dev, in the wrong order", "They rebuild a fresh artifact per environment instead of promoting the *same, already-built* artifact through each stage, reintroducing the exact ''it worked in staging but not prod'' risk promotion is meant to eliminate", "They skip the dev/preview environment entirely, going straight to staging", "They require manual approval for dev deploys but not for production deploys"]', 1, 'The content specifically flags rebuilding per environment as the common mistake -- different dependency resolution or baked-in environment variables from a fresh build reintroduces exactly the risk that promoting one already-built artifact through each stage is designed to eliminate.', 'advanced'),
('devops', 'cicd', 'intermediate', 'Why does the content recommend scoping a production deployment credential to only the deploy job, not the entire pipeline?', '["Because scoping credentials is required by GitHub''s terms of service", "So that a compromised test-stage dependency can''t exfiltrate production credentials it never needed access to in the first place", "Because unscoped credentials always expire faster than scoped ones", "Because scoping credentials makes the pipeline run measurably faster"]', 1, 'Secret scoping limits blast radius directly: if only the deploy job has production credentials, a compromised dependency in an earlier, unrelated stage (like the test stage) has no path to exfiltrate credentials it was never granted.', 'advanced'),
('devops', 'cicd', 'intermediate', 'Why is a short-lived OIDC token generally preferable to a long-lived static cloud access key stored as a pipeline secret?', '["OIDC tokens are always faster to authenticate with than static keys", "A leaked long-lived key is a standing liability until manually rotated; a leaked 15-minute OIDC token expires before it''s useful to an attacker", "OIDC tokens do not require any cloud provider configuration, unlike static keys", "Static keys cannot technically be used inside a CI/CD pipeline at all"]', 1, 'The security tradeoff is time-bounded exposure: a static key remains valid (and dangerous if leaked) until someone manually rotates it, while an OIDC-minted short-lived token naturally expires quickly, sharply limiting what a leak could actually be used for.', 'advanced'),
('devops', 'cicd', 'intermediate', 'What do the two common rollback approaches described (redeploy previous artifact, or blue-green/canary traffic routing) have in common?', '["Both require a full rebuild of the application from source before rollback can occur", "Neither is a rebuild -- both rely on something already known-good (a previous artifact, or a previous still-running environment) rather than reconstructing anything from scratch under incident pressure", "Both require the same manual approval process as a normal forward deployment", "Both are only usable for stateless services, never for services with a database"]', 1, 'The shared design principle is avoiding a rebuild during an incident: redeploying a previously-built, known-good artifact, or simply routing traffic back to a previous still-running environment, are both faster and safer than reconstructing anything from scratch under pressure.', 'intermediate'),
('devops', 'cicd', 'advanced', 'What is the key maturity difference between a canary deployment''s automated rollback and a human watching a dashboard for the same purpose?', '["There is no real difference -- both approaches deliver identical safety guarantees", "A canary that still needs a human to notice a problem and manually intervene has given up most of the safety benefit for the added complexity -- genuine value requires automated rollback logic tied to real metrics, not a human watching a dashboard", "Human-monitored canaries are always faster to roll back than automated ones", "Automated canary rollback is technically impossible without a service mesh"]', 1, 'The content is explicit that canary''s real value depends on genuinely automated, metrics-tied rollback -- a canary requiring a human to notice degradation manually has effectively given up most of the safety benefit while still carrying the added complexity.', 'advanced'),
('devops', 'cicd', 'advanced', 'In a GitOps model, why does the CI pipeline never holding production cluster credentials meaningfully shrink the blast radius of a compromised pipeline?', '["Because GitOps pipelines are inherently immune to any form of compromise", "The blast radius of a compromised CI/CD platform shrinks to ''can write to a Git repo,'' not ''has direct write access to production infrastructure'' -- a genuine security improvement since the CI platform (often third-party SaaS) never holds the more dangerous credential at all", "Because GitOps controllers automatically detect and block any malicious commits", "Because Git repositories cannot be modified by any automated process, only by humans"]', 1, 'The architectural inversion (pipeline updates Git, a cluster-internal controller pulls from it) means a compromised CI/CD platform''s worst-case capability is limited to writing to a Git repo -- a meaningfully smaller blast radius than direct production cluster write access.', 'advanced'),
('devops', 'cicd', 'advanced', 'Why is pinning a third-party GitHub Action to a specific commit SHA, rather than a mutable tag like v4, considered important advanced security practice?', '["Pinning to a SHA makes the workflow run measurably faster", "A mutable tag like v4 can silently change what code actually runs if the tag is ever moved to point at a different commit; pinning to a commit SHA removes that trust dependency entirely", "GitHub technically does not allow tags to be used in workflow files at all", "SHA pinning is required for the workflow to appear in the Actions marketplace"]', 1, 'A tag like v4 is mutable -- it can be repointed to a different commit at any time, silently changing what code a workflow executes. Pinning to an immutable commit SHA removes that trust dependency, closing a real supply-chain risk.', 'advanced'),
('devops', 'cicd', 'advanced', 'In multi-region pipeline design, why should a rollback in region A never depend on region B''s pipeline state?', '["Because different regions are technically required to run different application versions at all times", "Treating multi-region as N independent pipelines sharing a trigger, rather than one pipeline with a loop, keeps failure domains genuinely isolated -- a rollback shouldn''t be blocked or complicated by an unrelated region''s pipeline status", "Because cloud providers charge extra for any cross-region pipeline dependency", "Because region B''s pipeline state is never accessible from region A''s tooling for security reasons"]', 1, 'Independent rollback per region is specifically about failure-domain isolation -- if region A''s rollback depended on region B''s state, a problem in B could block or complicate fixing A, undermining the whole point of regional independence.', 'advanced'),
('devops', 'cicd', 'advanced', 'What is the actual causal mechanism behind DORA''s finding that deployment frequency correlates with organizational performance, per the advanced content?', '["Deploying more often directly causes higher revenue with no other factors involved", "Teams that deploy frequently are forced to keep each change small (since a large, infrequent deploy is too risky to ship often), and small changes are inherently easier to review, test, and roll back -- chasing frequency alone without that discipline just moves risk around faster", "Deployment frequency is purely a vanity metric with no real causal relationship to anything", "More frequent deployments always reduce a team''s total headcount requirements"]', 1, 'The content is explicit that the causal mechanism is change size, not frequency itself: frequent deployment forces smaller changes, and smaller changes are easier to review/test/roll back -- chasing the frequency number alone without that underlying discipline doesn''t actually reduce risk.', 'advanced')
